@startuml

class Driver {
  + ID : int
  + Name : string
  + IsSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + InRepairShop : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + ShiftType : ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class Schedule {
  + Date : date
}

class Assignment {
  + Date : date
}

Driver "1" -- "*" Schedule
Bus "1" -- "*" Assignment
Route "1" -- "*" Assignment
Schedule "1" *-- "1..*" Shift
Assignment "1" *-- "1" Shift
Assignment "1" *-- "1" Driver
Assignment "1" *-- "1" Bus
Assignment "1" *-- "1" Route

@enduml

